+  } catch {
+    throw new Error(`OpenUI action journal ${documentId} contains invalid JSON.`);
+  }
+  if (!validateUiActionJournal(journal) || journal.documentId !== documentId) {
+    throw new Error(`OpenUI action journal ${documentId} is invalid.`);
+  }
+  return journal;
+}
