151	  const topic = (value as Record<string, unknown>).topic;
152	  if (keys.length !== 1 || keys[0] !== "topic" || typeof topic !== "string") {
153	    return failure(toolName, context, "invalid_arguments", "Only a string topic argument is allowed.");
154	  }
155	  const normalized = topic.trim();
156	  if (normalized.length < 1 || normalized.length > 240) {
157	    return failure(toolName, context, "invalid_arguments", "Topic must contain between 1 and 240 characters.");
158	  }
159	  return { topic: normalized };
160	}
