162	function stableGeneratedContent(content: string, createdAt: number): string {
163	  return content.replace(/^> Generated: .*$/m, `> Generated: ${new Date(createdAt).toISOString()}`);
164	}
165	
166	export function executeMobileTool(
167	  toolName: string,
168	  rawArguments: string | Readonly<Record<string, unknown>>,
169	  context: MobileToolExecutionContext,
170	): MobileToolExecutionResult {
171	  if (!context.idempotencyKey.trim()) {
172	    return failure(toolName, context, "invalid_arguments", "A non-empty idempotency key is required.");
173	  }
174	  if (context.signal?.aborted) return failure(toolName, context, "aborted", "Tool execution was cancelled.", true);
175	  const now = context.now ?? Date.now;
176	  if (context.deadlineAt !== undefined && now() >= context.deadlineAt) {
177	    return failure(toolName, context, "timeout", "Tool execution exceeded its deadline.", true);
178	  }
179	  if (!Object.prototype.hasOwnProperty.call(TOOL_KINDS, toolName)) {
180	    return failure(toolName, context, "unknown_tool", `Tool ${toolName} is not available on mobile.`);
181	  }
182	  const parsed = parseArguments(toolName, rawArguments, context);
183	  if ("ok" in parsed) return parsed;
184	
185	  try {
186	    const kind = TOOL_KINDS[toolName as MobileToolName];
187	    const generated = generateLearningArtifact(parsed.topic, kind);
188	    if (context.signal?.aborted) return failure(toolName, context, "aborted", "Tool execution was cancelled.", true);
189	    if (context.deadlineAt !== undefined && now() >= context.deadlineAt) {
190	      return failure(toolName, context, "timeout", "Tool execution exceeded its deadline.", true);
191	    }
192	    const artifact: StudyArtifact = {
193	      id: `tool-artifact-${shortHash(context.idempotencyKey)}`,
194	      sessionId: context.sessionId,
195	      messageId: context.messageId,
196	      kind: generated.kind,
197	      source: "keating-core",
198	      topic: generated.topic,
199	      title: generated.title,
200	      content: stableGeneratedContent(generated.content, context.createdAt),
201	      createdAt: context.createdAt,
202	    };
203	    return {
204	      ok: true,
205	      toolName,
206	      idempotencyKey: context.idempotencyKey,
207	      output: Object.freeze({ artifactId: artifact.id, kind: artifact.kind, title: artifact.title, topic: artifact.topic }),
208	      effects: Object.freeze([Object.freeze({ type: "upsert-artifact", artifact: Object.freeze(artifact) })]),
209	    };
210	  } catch (error) {
211	    return failure(toolName, context, "execution_failed", error instanceof Error ? error.message : "Tool execution failed.", true);
212	  }
213	}

