 19	export const MAX_PROVIDER_TOOL_ROUNDS = 4;
 20	export const MAX_PROVIDER_CALLS_PER_ROUND = 8;
 21	const TOOL_TIMEOUT_MS = 10_000;
 22	
 23	export interface CommittedMobileToolCall {
 24	  call: ProviderToolCall;
 25	  idempotencyKey: string;
 26	  execution: MobileToolExecutionResult;
 27	}
 28	
 29	export interface MobileToolLoopResult {
 30	  text: string;
 31	  usage: ProviderUsage | null;
 32	  rounds: number;
 33	  toolCalls: number;
 34	}
 35	
 36	export interface RunMobileToolLoopOptions extends Omit<ProviderRequestOptions, "tools" | "continuation"> {
 37	  fetchImpl?: FetchLike;
 38	  sessionId: string;
 39	  triggeringMessageId: string;
 40	  assistantMessageId: string;
 41	  createdAt: number;
 42	  onIntermediateText?: (text: string, round: number) => void;
 43	  onToolCall?: (call: ProviderToolCall, idempotencyKey: string) => void;
 44	  commitToolCall: (committed: CommittedMobileToolCall) => Promise<void>;
 45	  requestRound?: typeof requestProviderRound;
 46	}
 47	
 48	function sumUsage(current: ProviderUsage | null, next: ProviderUsage | null): ProviderUsage | null {
 49	  if (!next) return current;
 50	  if (!current) return next;
 51	  return {
 52	    inputTokens: current.inputTokens + next.inputTokens,
 53	    outputTokens: current.outputTokens + next.outputTokens,
 54	    totalTokens: current.totalTokens + next.totalTokens,
 55	    ...(current.costUsd === undefined && next.costUsd === undefined
 56	      ? {}
 57	      : { costUsd: (current.costUsd ?? 0) + (next.costUsd ?? 0) }),
 58	  };
 59	}
 60	
 61	function providerResult(
 62	  call: ProviderToolCall,
 63	  execution: MobileToolExecutionResult,
 64	): ProviderToolResult {
 65	  return {
 66	    callId: call.id,
 67	    name: call.name,
 68	    output: execution.ok
 69	      ? { ok: true, ...execution.output }
 70	      : { ok: false, code: execution.code, message: execution.message, retryable: execution.retryable },
 71	    ...(!execution.ok ? { isError: true } : {}),
 72	  };
 73	}
 74	
 75	const PROVIDER_TOOL_DEFINITIONS: ProviderToolDefinition[] = MOBILE_TOOL_DEFINITIONS.map((tool) => ({
 76	  name: tool.name,
 77	  description: tool.description,
 78	  parameters: { ...tool.inputSchema },
 79	}));
 80	
 81	/** Applies proposed artifact effects as idempotent upserts, newest effect first. */
 82	export function applyMobileToolArtifactEffects(
 83	  current: readonly StudyArtifact[],
 84	  execution: MobileToolExecutionResult,
 85	): StudyArtifact[] {
 86	  if (!execution.ok) return [...current];
 87	  const proposed = execution.effects.map((effect) => effect.artifact);
 88	  const proposedIds = new Set(proposed.map((artifact) => artifact.id));
 89	  return [...proposed, ...current.filter((artifact) => !proposedIds.has(artifact.id))];
 90	}
 91	
 92	/** Runs a bounded provider-native call/result loop and commits each effect before continuation. */
 93	export async function runMobileToolLoop(
 94	  settings: ProviderSettings,
 95	  apiKey: string | null,
 96	  messages: ChatMessage[],
 97	  options: RunMobileToolLoopOptions,
 98	): Promise<MobileToolLoopResult> {
 99	  const {
100	    fetchImpl,
101	    sessionId,
102	    triggeringMessageId,
103	    assistantMessageId,
104	    createdAt,
105	    onIntermediateText,
106	    onToolCall,
107	    commitToolCall,
108	    requestRound = requestProviderRound,
109	    ...providerOptions
110	  } = options;
111	  let continuation: ProviderRequestOptions["continuation"];
112	  let usage: ProviderUsage | null = null;
113	  let totalCalls = 0;
114	  const semanticKeys = new Set<string>();
115	
116	  for (let roundIndex = 0; roundIndex < MAX_PROVIDER_TOOL_ROUNDS; roundIndex += 1) {
117	    if (providerOptions.signal?.aborted) throw new DOMException("The response was cancelled.", "AbortError");
118	    const round: ProviderRound = await requestRound(settings, apiKey, messages, {
119	      ...providerOptions,
120	      fetchImpl,
121	      tools: PROVIDER_TOOL_DEFINITIONS,
122	      continuation,
123	    });
124	    usage = sumUsage(usage, round.usage);
125	    if (round.calls.length === 0) {
126	      if (!round.text.trim()) throw new Error("The provider finished the tool loop without a teaching response.");
127	      return { text: round.text, usage, rounds: roundIndex + 1, toolCalls: totalCalls };
128	    }
129	    if (!round.assistantTurn) throw new Error("The provider omitted the assistant turn required to continue tool results.");
130	    if (round.calls.length > MAX_PROVIDER_CALLS_PER_ROUND) {
131	      throw new Error(`The provider requested ${round.calls.length} tools in one round; the mobile safety limit is ${MAX_PROVIDER_CALLS_PER_ROUND}.`);
132	    }
133	    if (round.text.trim()) onIntermediateText?.(round.text, roundIndex);
134	
135	    const results: ProviderToolResult[] = [];
136	    for (const call of round.calls) {
137	      if (providerOptions.signal?.aborted) throw new DOMException("The response was cancelled.", "AbortError");
138	      const idempotencyKey = mobileToolIdempotencyKey(
139	        sessionId,
140	        triggeringMessageId,
141	        call.name,
142	        call.arguments,
143	      );
144	      if (semanticKeys.has(idempotencyKey)) {
145	        throw new Error(`The provider repeated ${call.name} in the same turn. The effect was not applied twice.`);
146	      }
147	      semanticKeys.add(idempotencyKey);
148	      onToolCall?.(call, idempotencyKey);
149	      const execution = executeMobileTool(call.name, call.arguments, {
150	        idempotencyKey,
151	        createdAt,
152	        sessionId,
153	        messageId: assistantMessageId,
154	        signal: providerOptions.signal,
155	        deadlineAt: Date.now() + TOOL_TIMEOUT_MS,
156	      });
157	      await commitToolCall({ call, idempotencyKey, execution });
158	      results.push(providerResult(call, execution));
159	      totalCalls += 1;
160	    }
161	    continuation = continueProviderTurn(round.assistantTurn, results);
162	  }
163	
164	  throw new Error(`The provider exceeded the ${MAX_PROVIDER_TOOL_ROUNDS}-round mobile tool safety limit.`);
165	}

